// Map-local visibility for PART7 actors. Temp flags only, no save cost.
void Part7_SyncMap(void)
{
    u16 map = (gSaveBlock1Ptr->location.mapGroup << 8) | gSaveBlock1Ptr->location.mapNum;
    if (map == MAP_ROUTE119)
    {
        if (FlagGet(FLAG_BADGE08_GET)) FlagClear(FLAG_TEMP_8); else FlagSet(FLAG_TEMP_8);
        if (FlagGet(FLAG_PART7_LATI_MET) && !FlagGet(FLAG_PART7_LATI_119_DONE) && VarGet(VAR_ROAMER_POKEMON) == 0) FlagClear(FLAG_TEMP_9); else FlagSet(FLAG_TEMP_9);
        if (FlagGet(FLAG_PART7_LATI_MET) && !FlagGet(FLAG_PART7_LATI_119_DONE) && VarGet(VAR_ROAMER_POKEMON) != 0) FlagClear(FLAG_TEMP_A); else FlagSet(FLAG_TEMP_A);
        if (FALSE) FlagClear(FLAG_TEMP_B); else FlagSet(FLAG_TEMP_B);
    }
    if (map == MAP_JAGGED_PASS)
    {
        if (FlagGet(FLAG_BADGE08_GET)) FlagClear(FLAG_TEMP_8); else FlagSet(FLAG_TEMP_8);
    }
    if (map == MAP_LAVARIDGE_TOWN_POKEMON_CENTER_1F)
    {
        if (FlagGet(FLAG_BADGE08_GET)) FlagClear(FLAG_TEMP_8); else FlagSet(FLAG_TEMP_8);
    }
    if (map == MAP_ROUTE128)
    {
        if (FlagGet(FLAG_BADGE08_GET)) FlagClear(FLAG_TEMP_8); else FlagSet(FLAG_TEMP_8);
    }
    if (map == MAP_METEOR_FALLS_DRAGON_NEST)
    {
        if (!FlagGet(FLAG_PART7_BAGON_CAUGHT)) FlagClear(FLAG_TEMP_7); else FlagSet(FLAG_TEMP_7);
    }
    if (map == MAP_EVER_GRANDE_CITY_POKEMON_CENTER_1F)
    {
        if (FlagGet(FLAG_PART7_SISTER_DONE)) FlagClear(FLAG_TEMP_7); else FlagSet(FLAG_TEMP_7);
    }
    if (map == MAP_VICTORY_ROAD_B2F)
    {
        if (!FlagGet(FLAG_PART7_RIOLU_CAUGHT)) FlagClear(FLAG_TEMP_7); else FlagSet(FLAG_TEMP_7);
        if (!FlagGet(FLAG_PART7_SISTER_BRACE)) FlagClear(FLAG_TEMP_8); else FlagSet(FLAG_TEMP_8);
    }
    if (map == MAP_SLATEPORT_CITY_HARBOR)
    {
        if ((FlagGet(FLAG_LATIOS_OR_LATIAS_ROAMING) && !FlagGet(FLAG_PART7_LATI_119_DONE)) || FlagGet(FLAG_PART7_LATI_REUNION)) FlagClear(FLAG_TEMP_7); else FlagSet(FLAG_TEMP_7);
    }
    if (map == MAP_SOUTHERN_ISLAND_INTERIOR)
    {
        if (FlagGet(FLAG_PART7_LATI_119_DONE) && !((VarGet(VAR_ROAMER_POKEMON) == 0) ? FlagGet(FLAG_PART7_LATIOS_CAUGHT) : FlagGet(FLAG_PART7_LATIAS_CAUGHT))) FlagClear(FLAG_TEMP_7); else FlagSet(FLAG_TEMP_7);
        if (FlagGet(FLAG_PART7_LATI_REUNION) && !((VarGet(VAR_ROAMER_POKEMON) == 0) ? FlagGet(FLAG_PART7_LATIAS_CAUGHT) : FlagGet(FLAG_PART7_LATIOS_CAUGHT))) FlagClear(FLAG_TEMP_8); else FlagSet(FLAG_TEMP_8);
        if (FlagGet(FLAG_PART7_LATI_119_DONE) && !FlagGet(FLAG_PART7_LATI_REUNION)) FlagClear(FLAG_TEMP_9); else FlagSet(FLAG_TEMP_9);
    }
}

// Meteor Falls dragon nest Bagon: fixed Lv35, Speed IV 31, never shiny; caught = permanent.
void Part7_PrepareBagon(void)
{
    struct Pokemon *mon = &gParties[B_TRAINER_OPPONENT_A][0];
    u8 iv = 31;
    bool8 shiny = FALSE;
    SetMonData(mon, MON_DATA_SPEED_IV, &iv);
    SetMonData(mon, MON_DATA_IS_SHINY, &shiny);
    CalculateMonStats(mon);
}

void Part7_FinishBagon(void)
{
    if (gBattleOutcome == B_OUTCOME_CAUGHT)
        FlagSet(FLAG_PART7_BAGON_CAUGHT);
}

// Fixed encounters: setvar VAR_0x8005, FLAG_X before the battle; caught = permanent.
void Part7_SetFlagIfCaught(void)
{
    if (gBattleOutcome == B_OUTCOME_CAUGHT)
        FlagSet(gSpecialVar_0x8005);
}

// Wally's post-Champion rematch: VAR_RESULT = TRUE when the battle just won was his final tier.
void Part7_IsWallyFinalTier(void)
{
    gSpecialVar_Result = (TRAINER_BATTLE_PARAM.opponentA == TRAINER_WALLY_VR_5);
}

// The Primal Adjuster cannot be used anywhere inside the League facility (§71).
void Part7_IsLeagueMap(void)
{
    u16 map = (gSaveBlock1Ptr->location.mapGroup << 8) | gSaveBlock1Ptr->location.mapNum;
    gSpecialVar_Result = (map >= MAP_EVER_GRANDE_CITY_SIDNEYS_ROOM && map <= MAP_EVER_GRANDE_CITY_HALL_OF_FAME)
                      || map == MAP_EVER_GRANDE_CITY_POKEMON_LEAGUE_2F;
}

// Battle Frontier competitive-item exchange (§134-136). Mega stones and story key items are never sold here.
static const u16 sPart7BpItems[][2] =
{
    {ITEM_CHOICE_SPECS, 48},
    {ITEM_CHOICE_SCARF, 48},
    {ITEM_LIFE_ORB, 48},
    {ITEM_FOCUS_SASH, 48},
    {ITEM_ROCKY_HELMET, 48},
    {ITEM_ASSAULT_VEST, 48},
    {ITEM_EVIOLITE, 48},
    {ITEM_POWER_HERB, 32},
    {ITEM_EXPERT_BELT, 48},
    {ITEM_PP_UP, 16},
    {ITEM_ABILITY_CAPSULE, 32},
    {ITEM_ADAMANT_MINT, 24},
    {ITEM_MODEST_MINT, 24},
    {ITEM_JOLLY_MINT, 24},
    {ITEM_TIMID_MINT, 24},
    {ITEM_ABILITY_PATCH, 128},
};

// VAR_0x8004 = menu index -> VAR_RESULT 0 bought, 1 not enough BP, 2 bag full
void Part7_BuyBpItem(void)
{
    u16 i = gSpecialVar_0x8004;
    if (i >= ARRAY_COUNT(sPart7BpItems))
    {
        gSpecialVar_Result = 1;
        return;
    }
    if (gSaveBlock2Ptr->frontier.battlePoints < sPart7BpItems[i][1])
        gSpecialVar_Result = 1;
    else if (!CheckBagHasSpace(sPart7BpItems[i][0], 1))
        gSpecialVar_Result = 2;
    else
    {
        gSaveBlock2Ptr->frontier.battlePoints -= sPart7BpItems[i][1];
        AddBagItem(sPart7BpItems[i][0], 1);
        gSpecialVar_Result = 0;
    }
}
